// Zen Maru Gothic as three subsets a weight (500, 700), our own files (src/lib/styles/fonts/), so the render-blocking CSS
// is 6 @font-face rules (it was @fontsource's 160 unicode-range slices, 30 KB gzipped) and a phone's caches hold 6 font
// files, not ~125 (each an entry a cold service worker's first cache read walks: docs/ops/perf.md):
//   kana:  everything the font has but the kanji (Latin, Greek, Cyrillic, symbols, kana, full-width forms), ~80 KB;
//   joyo:  the 2,136 常用漢字 (scripts/data/joyo.txt, the 2010 list), ~440 KB, never
//          regenerated by new copy, so a phone downloads it once;
//   extra: the other kanji the app shows (any in src/: catalogs, names, the English banks' Japanese) and those in the food
//          data at least FOOD_MIN times (product and chain-menu names, 99.9 % of their kanji with joyo), ~85 KB.
// A kanji in none (a rare one a user types in a food's name or a note) falls back to the system's rounded font.
// And one more a weight, for ジム's page alone (/gym, the LINE menu's link: a cold phone with no service worker, on
// mobile data): gym, the characters its text can hold (gymWanted: ASCII, the kana, and every character of the page's
// sources, the catalog keys they name and the bot's own words), where kana and joyo were ~600 KB. fonts-gym.css
// (imported by routes/gym/+page.svelte only) declares it as its own family, first in --font-zmg (tokens.css), so any
// other character still falls back to the six.
// fonts.css lists joyo by its blocks and kana and extra by their code points; extra is declared last, so it's the face
// tried first for its own (CSS Fonts: the last rule of overlapping ranges first). ranges.json: each subset's exact
// ranges (the maps' font faces, components/map/fonts.ts).
// Usage (from app/): npm run fonts:subset → src/lib/styles/fonts/ and fonts.css (commit them). Needs Python's fonttools
// with brotli (`pip install fonttools brotli`; PYTHON=<interpreter> to pick one). The source fonts (Google Fonts' TTFs,
// SHA-256 checked) are downloaded once into .cache/zen-maru-gothic/. src/lib/styles/fonts.test.ts checks that every
// character in src/ the font has is in a subset, so re-run this after adding copy with a new kanji outside 常用 (or a
// character new to ジム's page: the same test checks gym; the six come out byte for byte the same).
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { brotliDecompressSync } from 'node:zlib';

const APP = join(import.meta.dirname, '..');
/** @fontsource's full set of slices: the whole font's coverage (fonts.test.ts) and the trip map's rare kanji. */
export const PKG = join(APP, 'node_modules', '@fontsource', 'zen-maru-gothic');
const STYLES = join(APP, 'src', 'lib', 'styles');
export const FONT_DIR = join(STYLES, 'fonts');
const CSS = join(STYLES, 'fonts.css');
const GYM_CSS = join(STYLES, 'fonts-gym.css');
/** ジム's page's own family (fonts-gym.css), tried before the six (tokens.css --font-zmg). */
export const GYM_FAMILY = 'Zen Maru Gothic Gym';
export const gymFile = (w: number) => `zen-maru-gothic-${w}-gym.woff2`;
export const WEIGHTS = [500, 700] as const;
export const PARTS = ['kana', 'joyo', 'extra'] as const;
export type Part = (typeof PARTS)[number];
const SOURCES: Record<(typeof WEIGHTS)[number], { name: string; sha256: string }> = {
  500: { name: 'ZenMaruGothic-Medium.ttf', sha256: '3cfdb98a13571ede17fcc769f5093a97c38b80a7b9b2ab754a26b4d822092b3b' },
  700: { name: 'ZenMaruGothic-Bold.ttf', sha256: 'fe24426b9c8b5523a0146a8235c8674eccf0493af354a53ec895c3596d9eb745' }
};
const SOURCE_URL = 'https://github.com/google/fonts/raw/main/ofl/zenmarugothic/';
/** A food data kanji outside 常用 in at least this many places goes into extra. */
const FOOD_MIN = 5;
/** The CJK ideograph blocks (joyo's unicode-range; kana is the rest). */
const KANJI_BLOCKS: [number, number][] = [[0x3400, 0x4dbf], [0x4e00, 0x9fff], [0xf900, 0xfaff], [0x20000, 0x3ffff]];

export const fontFile = (w: number, part: Part) => `zen-maru-gothic-${w}-${part}.woff2`;
const isKanji = (cp: number) => KANJI_BLOCKS.some(([a, b]) => cp >= a && cp <= b);

const hex = (n: number) => n.toString(16);
/** Sorted code points → `U+a-b,U+c`. */
export function toRanges(cps: Iterable<number>): string {
  const s = [...new Set(cps)].sort((a, b) => a - b), out: string[] = [];
  for (let i = 0; i < s.length; i++) {
    let j = i;
    while (j + 1 < s.length && s[j + 1] === s[j] + 1) j++;
    out.push(j > i ? `U+${hex(s[i])}-${hex(s[j])}` : `U+${hex(s[i])}`);
    i = j;
  }
  return out.join(',');
}

/** The code points a woff2 file maps to a glyph (its cmap: format 4 or 12), read from the file itself. */
export function cmapOf(file: string): Set<number> {
  const b = readFileSync(file);
  if (b.toString('latin1', 0, 4) !== 'wOF2') throw new Error(`${file}: not a woff2`);
  const numTables = b.readUInt16BE(12), compressed = b.readUInt32BE(20);
  let p = 48, cmapAt = -1, cmapLen = 0, at = 0;
  const base128 = () => {
    let v = 0;
    for (let i = 0; i < 5; i++) {
      const d = b[p++];
      v = v * 128 + (d & 0x7f);
      if (!(d & 0x80)) return v;
    }
    throw new Error(`${file}: bad UIntBase128`);
  };
  for (let t = 0; t < numTables; t++) {
    const flags = b[p++], tag = flags & 0x3f, version = flags >> 6;
    if (tag === 63) p += 4;
    const orig = base128();
    // glyf (10) and loca (11) are transformed at version 0, every other table at any other version
    const transformed = tag === 10 || tag === 11 ? version === 0 : version !== 0;
    const len = transformed ? base128() : orig;
    if (tag === 0) [cmapAt, cmapLen] = [at, len];
    at += len;
  }
  if (cmapAt < 0) throw new Error(`${file}: no cmap`);
  const c = brotliDecompressSync(b.subarray(p, p + compressed)).subarray(cmapAt, cmapAt + cmapLen);
  const out = new Set<number>();
  for (let i = 0, n = c.readUInt16BE(2); i < n; i++) {
    const off = c.readUInt32BE(4 + i * 8 + 4), format = c.readUInt16BE(off);
    if (format === 12) {
      for (let g = 0, groups = c.readUInt32BE(off + 12); g < groups; g++) {
        const at12 = off + 16 + g * 12;
        for (let cp = c.readUInt32BE(at12); cp <= c.readUInt32BE(at12 + 4); cp++) out.add(cp);
      }
    } else if (format === 4) {
      const segs = c.readUInt16BE(off + 6) / 2, ends = off + 14, starts = ends + segs * 2 + 2, deltas = starts + segs * 2, offs = deltas + segs * 2;
      for (let s = 0; s < segs; s++) {
        const end = c.readUInt16BE(ends + s * 2), start = c.readUInt16BE(starts + s * 2), delta = c.readUInt16BE(deltas + s * 2), ro = c.readUInt16BE(offs + s * 2);
        for (let cp = start; cp <= end && cp !== 0xffff; cp++) {
          const g = ro === 0 ? (cp + delta) & 0xffff : ((x) => (x === 0 ? 0 : (x + delta) & 0xffff))(c.readUInt16BE(offs + s * 2 + ro + (cp - start) * 2));
          if (g) out.add(cp);
        }
      }
    }
  }
  return out;
}

let shipped: Set<number>[] | undefined;
/** What each weight's subsets show between them (their files' own cmaps). */
export const shippedCover = (): Set<number>[] =>
  (shipped ??= WEIGHTS.map((w) => new Set(PARTS.flatMap((part) => [...cmapOf(join(FONT_DIR, fontFile(w, part)))]))));

let whole: Set<number>[] | undefined;
/** What the whole font has, each weight: @fontsource's slices' own cmaps (their unicode-ranges name more than the font
 *  has: ～, ✓, ō… are drawn in a fallback whatever the subsets). */
export const fullCover = (): Set<number>[] =>
  (whole ??= WEIGHTS.map((w) => new Set(readdirSync(join(PKG, 'files')).filter((f) => f.endsWith(`-${w}-normal.woff2`) && !f.includes('japanese'))
    .flatMap((f) => [...cmapOf(join(PKG, 'files', f))]))));

/** The characters of `text` the font has but the subsets (either weight) don't: the content tests' check, so a file
 *  names the word to change (or `npm run fonts:subset` to run) instead of fonts.test.ts failing on the whole of src/. */
export function notInTrimmedFont(text: string): string[] {
  return [...text].filter((ch) => {
    const cp = ch.codePointAt(0)!;
    return cp > 0x7f && WEIGHTS.some((_, i) => fullCover()[i].has(cp) && !shippedCover()[i].has(cp));
  });
}

function walk(dir: string, out: string[] = []): string[] {
  for (const f of readdirSync(dir)) {
    const p = join(dir, f);
    if (statSync(p).isDirectory()) {
      // (トレイル's text is in the system fonts, its own look: docs/hiking.md)
      if (f !== 'fixtures' && f !== 'hiking') walk(p, out);
    // (places-facets/descs: the vendored Google text packed for the search, static/places/'s own, unscanned; the kinds'
    // and the gazetteer's names are chip labels: scanned)
    } else if (/\.(svelte|ts|json)$/.test(f) && !/\.test\.ts$/.test(f) && !/^places-(facets|descs)\.json$/.test(f)) out.push(p);
  }
  return out;
}

/** Code points the app's own files use, which must render in Zen Maru Gothic (also used by fonts.test.ts). */
export function wanted(): Set<number> {
  const cps = new Set<number>();
  for (const f of walk(join(APP, 'src'))) {
    // Code and copy only: comments are full of kanji nobody sees.
    const text = readFileSync(f, 'utf8').replace(/\/\*[\s\S]*?\*\/|<!--[\s\S]*?-->|(^|[^:'"`\\])\/\/[^\n]*/g, '$1');
    for (const ch of text) cps.add(ch.codePointAt(0)!);
  }
  return cps;
}

/** Code and copy only: comments are full of kanji nobody sees. */
const uncommented = (text: string) => text.replace(/\/\*[\s\S]*?\*\/|<!--[\s\S]*?-->|(^|[^:'"`\\])\/\/[^\n]*/g, '$1');

/** ジム's page's modules: the static imports from its route and the root layout, transitively, in src/ (not a type-only
 *  import: its module is no code of the page's). */
function gymModules(): string[] {
  const seen = new Set<string>(), queue = ['src/routes/gym/+page.svelte', 'src/routes/+layout.svelte'].map((f) => join(APP, f));
  const resolve = (from: string, spec: string): string | null => {
    const p = spec.startsWith('#lib/') ? join(APP, 'src', 'lib', spec.slice(5)) : spec.startsWith('.') ? join(dirname(from), spec) : null;
    return (p && [p, `${p}.ts`].find((c) => existsSync(c) && statSync(c).isFile())) || null;
  };
  const typeOnly = (names: string) => /^\s*\{[^}]*\}\s*from\s*$/.test(names) && names.replace(/^\s*\{|\}\s*from\s*$/g, '').split(',').every((x) => !x.trim() || /^type\s/.test(x.trim()));
  while (queue.length) {
    const f = queue.shift()!;
    if (seen.has(f)) continue;
    seen.add(f);
    if (f.endsWith('.json')) continue;
    for (const m of uncommented(readFileSync(f, 'utf8')).matchAll(/(?:^|[\s;])import\s+(type\s)?([^'"`;]*?\sfrom\s*)?['"]([^'"]+)['"]/g)) {
      if (m[1] || (m[2] && typeOnly(m[2]))) continue;
      const r = resolve(f, m[3]);
      if (r?.startsWith(join(APP, 'src'))) queue.push(r);
    }
  }
  return [...seen];
}

/** The characters ジム's page can show: ASCII and the kana whole (names, the bot's words), and every character of its
 *  modules (gymModules: code and copy, the gym and bots catalogs), of the app catalog's (i18n/ja.json) strings they
 *  name (a key, or a `prefix.${…}` one), and of the bot's own words (gym/src/messages.ts: its replies and hints). */
export function gymWanted(): Set<number> {
  const cps = new Set<number>();
  const add = (text: string) => {
    for (const ch of text) cps.add(ch.codePointAt(0)!);
  };
  for (const [a, b] of [[0x20, 0x7e], [0x3041, 0x3096], [0x309b, 0x309e], [0x30a1, 0x30fa], [0x30fc, 0x30fe]]) for (let cp = a; cp <= b; cp++) cps.add(cp);
  const ja = JSON.parse(readFileSync(join(APP, 'src', 'lib', 'i18n', 'ja.json'), 'utf8')) as Record<string, string>;
  const keys = Object.keys(ja);
  for (const f of gymModules()) {
    if (f.endsWith('/i18n/ja.json')) continue;
    const text = f.endsWith('.json') ? Object.values(JSON.parse(readFileSync(f, 'utf8')) as Record<string, string>).join('\n') : uncommented(readFileSync(f, 'utf8'));
    add(text);
    const prefixes = [...text.matchAll(/`([\w.]+)\.\$\{/g)].map((m) => `${m[1]}.`);
    for (const k of keys) if (text.includes(`'${k}'`) || text.includes(`"${k}"`) || prefixes.some((p) => k.startsWith(p))) add(ja[k]);
  }
  add(uncommented(readFileSync(join(APP, '..', 'gym', 'src', 'messages.ts'), 'utf8')));
  return cps;
}

/** The 常用漢字 (the 2010 list) and the other form of its four with two (叱 𠮟, 填 塡, 剥 剝, 頬 頰: the font has one
 *  of each). */
export const joyo = (): Set<number> =>
  new Set([...readFileSync(join(APP, 'scripts', 'data', 'joyo.txt'), 'utf8').trim(), ...'𠮟填剝頬'].map((c) => c.codePointAt(0)!));

/** Kanji outside 常用 in the food data (static/food/: names users search and log) at least FOOD_MIN times. */
function foodKanji(not: Set<number>): number[] {
  const n = new Map<number, number>();
  const each = (d: string) => {
    for (const f of readdirSync(d)) {
      const p = join(d, f);
      if (statSync(p).isDirectory()) each(p);
      else if (f.endsWith('.json')) for (const ch of readFileSync(p, 'utf8')) {
        const cp = ch.codePointAt(0)!;
        if (isKanji(cp) && !not.has(cp)) n.set(cp, (n.get(cp) ?? 0) + 1);
      }
    }
  };
  each(join(APP, 'static', 'food'));
  return [...n].filter(([, k]) => k >= FOOD_MIN).map(([cp]) => cp);
}

const PY = process.env.PYTHON ?? 'python3';
async function source(w: (typeof WEIGHTS)[number]): Promise<string> {
  const dir = join(APP, '.cache', 'zen-maru-gothic'), { name, sha256 } = SOURCES[w], file = join(dir, name);
  if (!existsSync(file)) {
    mkdirSync(dir, { recursive: true });
    const res = await fetch(SOURCE_URL + name);
    if (!res.ok) throw new Error(`${SOURCE_URL + name}: ${res.status}`);
    writeFileSync(file, Buffer.from(await res.arrayBuffer()));
  }
  const got = createHash('sha256').update(readFileSync(file)).digest('hex');
  if (got !== sha256) throw new Error(`${file}: SHA-256 ${got}, expected ${sha256} (a new release upstream? check it, then update SOURCES)`);
  return file;
}
/** The source font's code points (fontTools). */
const sourceCmap = (file: string): Set<number> =>
  new Set(JSON.parse(execFileSync(PY, ['-c', 'import json,sys\nfrom fontTools.ttLib import TTFont\nprint(json.dumps(sorted(TTFont(sys.argv[1]).getBestCmap())))', file], { encoding: 'utf8' })) as number[]);

async function main() {
  const files = await Promise.all(WEIGHTS.map(source));
  const has = sourceCmap(files[0]);
  const j = joyo(), use = wanted();
  const parts: Record<Part, number[]> = {
    kana: [...has].filter((cp) => !isKanji(cp)),
    joyo: [...j].filter((cp) => has.has(cp)),
    extra: [...new Set([...[...use].filter(isKanji), ...foodKanji(j)])].filter((cp) => has.has(cp) && !j.has(cp))
  };
  rmSync(FONT_DIR, { recursive: true, force: true });
  mkdirSync(FONT_DIR, { recursive: true });
  const blocks: string[] = [];
  for (const [i, w] of WEIGHTS.entries()) {
    for (const part of PARTS) {
      const out = join(FONT_DIR, fontFile(w, part));
      execFileSync(PY, ['-m', 'fontTools.subset', files[i], `--unicodes=${parts[part].map(hex).join(',')}`, '--flavor=woff2', '--no-hinting', '--drop-tables+=vhea,vmtx,DSIG', `--output-file=${out}`]);
      const range = part === 'joyo' ? KANJI_BLOCKS.map(([a, b]) => `U+${hex(a)}-${hex(b)}`).join(',') : toRanges(parts[part]);
      blocks.push(`@font-face {\n  font-family: 'Zen Maru Gothic';\n  font-style: normal;\n  font-display: swap;\n  font-weight: ${w};\n  src: url(./fonts/${fontFile(w, part)}) format('woff2');\n  unicode-range: ${range};\n}`);
      console.log(`${fontFile(w, part)}: ${parts[part].length} characters, ${(statSync(out).size / 1024).toFixed(1)} KB`);
    }
  }
  // ジム's page's own (fonts-gym.css): what the font has of gymWanted, both weights, each declared by its file's own
  // characters (the subsetter keeps a few more: ‹ with ›)
  const gymCps = [...gymWanted()].filter((cp) => has.has(cp));
  const gymBlocks: string[] = [];
  for (const [i, w] of WEIGHTS.entries()) {
    const out = join(FONT_DIR, gymFile(w));
    execFileSync(PY, ['-m', 'fontTools.subset', files[i], `--unicodes=${gymCps.map(hex).join(',')}`, '--flavor=woff2', '--no-hinting', '--drop-tables+=vhea,vmtx,DSIG', `--output-file=${out}`]);
    gymBlocks.push(`@font-face {\n  font-family: '${GYM_FAMILY}';\n  font-style: normal;\n  font-display: swap;\n  font-weight: ${w};\n  src: url(./fonts/${gymFile(w)}) format('woff2');\n  unicode-range: ${toRanges(cmapOf(out))};\n}`);
    console.log(`${gymFile(w)}: ${gymCps.length} characters, ${(statSync(out).size / 1024).toFixed(1)} KB`);
  }
  writeFileSync(GYM_CSS, `/* Generated by scripts/font-subsets.ts: ジム's page's own Zen Maru Gothic (routes/gym/+page.svelte imports it), ${WEIGHTS.join(' + ')}, the characters its text can hold; tried first (tokens.css --font-zmg), any other falls back to fonts.css's. */\n${gymBlocks.join('\n')}\n:root { --font-zmg: '${GYM_FAMILY}', 'Zen Maru Gothic'; }\n`);
  writeFileSync(join(FONT_DIR, 'ranges.json'), `${JSON.stringify(Object.fromEntries(PARTS.map((p) => [p, toRanges(parts[p])])), null, 1)}\n`);
  writeFileSync(CSS, `/* Generated by scripts/font-subsets.ts: Zen Maru Gothic ${WEIGHTS.join(' + ')}, kana · 常用 · the app's other kanji (extra: last, tried first for its own). */\n${blocks.join('\n')}\n`);
}

if (import.meta.main ?? process.argv[1]?.endsWith('font-subsets.ts')) await main();
